import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.QWVCgkrI.js";const d="/study/images/game/asset-build-and-patches.svg",u=JSON.parse('{"title":"ゲームのアセットビルドと差分配信","description":"","frontmatter":{"title":"ゲームのアセットビルドと差分配信","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"制作元データを対象機種向けに変換し、依存と更新頻度に合わせて配信単位を組む。内容ハッシュによる再利用、マニフェスト、更新時の検証と切り替えを扱う。","aliases":["asset build","cook","アセットビルド","差分配信","差分パッチ","コンテンツ更新","content hash","manifest","チャンク","patch amplification"],"verification":"Epic GamesとUnityのコンテンツビルド・更新資料に照合（2026-11-06）"}},"headers":[],"relativePath":"game/asset-build-and-patches.md","filePath":"game/asset-build-and-patches.md"}'),o={name:"game/asset-build-and-patches.md"};function s(i,e,c,l,h,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ゲームのアセットビルドと差分配信" tabindex="-1">ゲームのアセットビルドと差分配信 <a class="header-anchor" href="#ゲームのアセットビルドと差分配信" aria-label="Permalink to &quot;ゲームのアセットビルドと差分配信&quot;">​</a></h1><p>街の看板を一枚描き直したとき、プレイヤーが再取得する量は画像一枚の大きさだけでは決まりません。配布用のどのファイルが変わり、ランチャーがどの単位で旧版を再利用できるかで決まります。たとえば、ほとんど更新しない地形と頻繁に変える看板を別々に配信すると、看板の更新で地形を再取得する必要がなくなります。Unreal Engineでは、アセットを独立して配布できるチャンクに分ける機能があります。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/cooking-content-and-creating-chunks-in-unreal-engine" target="_blank" rel="noreferrer">Epic Gamesのクックとチャンク</a></p><h2 id="制作元データを機種ごとの配布物にする" tabindex="-1">制作元データを機種ごとの配布物にする <a class="header-anchor" href="#制作元データを機種ごとの配布物にする" aria-label="Permalink to &quot;制作元データを機種ごとの配布物にする&quot;">​</a></h2><p>インポートでは、画像やモデルを制作環境で扱えるデータに変換します。<strong>クック</strong>では、使う機種や設定に合わせて、実行時に扱うデータを生成します。たとえばテクスチャを対象GPUで使う形式へ変換し、必要なmipレベルを作ります。ビルド時にはステージが参照するモデル、マテリアル、テクスチャを依存関係から集め、配布物に含めます。プラットフォームや品質設定が変わると、同じ制作元から異なる配布データができます。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/packaging-your-project" target="_blank" rel="noreferrer">Epic GamesのCook・Stage・Package</a> · <a href="/study/game/asset-loading.html">実行時のアセットロード</a></p><table tabindex="0"><thead><tr><th>識別する対象</th><th>例</th><th>主な用途</th></tr></thead><tbody><tr><td>論理アセットID</td><td><code>town/signboard</code></td><td>ゲーム内の参照先を更新後も保つ。</td></tr><tr><td>ビルド入力のキー</td><td>元画像、変換設定、対象機種、依存データ、変換ツールの版</td><td>以前のクック結果を再利用できるか判断する。</td></tr><tr><td>配布物の内容ハッシュ</td><td>生成したパックのバイト列のSHA-256</td><td>どのバイト列を取得・再利用するか特定し、受け取った内容を検査する。</td></tr></tbody></table><p>たとえば変換ツールの版や依存する設定をビルド入力のキーに含めると、それらが変わったときに対象を作り直せます。配布物をまとめる際は、同じ入力に対してファイルの並び順、書き出すメタデータ、圧縮設定を安定させます。現在時刻がヘッダーに入る形式では、内容が同じでもハッシュが変わります。同一の入力を別の作業領域で二度ビルドし、出力のハッシュを比較すると、どこに差が入ったか調べられます。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/cplusplus-cooking-development-reference" target="_blank" rel="noreferrer">Epic Gamesのクック依存関係</a> · <a href="https://reproducible-builds.org/docs/source-date-epoch/" target="_blank" rel="noreferrer">Reproducible Buildsのタイムスタンプ規約</a></p><h2 id="一緒に読む範囲と、一緒に更新する範囲を考える" tabindex="-1">一緒に読む範囲と、一緒に更新する範囲を考える <a class="header-anchor" href="#一緒に読む範囲と、一緒に更新する範囲を考える" aria-label="Permalink to &quot;一緒に読む範囲と、一緒に更新する範囲を考える&quot;">​</a></h2><p>同じレベルで一緒に使うデータを近くに配置すると、読み取りをまとめやすくなります。一方、毎週更新するイベント素材と、ほとんど変わらない共通素材を一つの配信単位にすると、更新のたびに広い範囲が差し替わりやすくなります。少数の大きなパックは管理が簡単ですが、一単位あたりの再取得量が大きくなります。細かく分けると更新対象は絞りやすくなり、配布物の数や、複数の単位にまたがる依存関係が増えます。頻繁なロードと頻繁な更新の両方を代表する場面で、読み取り量と再取得量を測ります。<a href="/study/game/asset-pack-files.html">パック内の配置と読み取り</a> · <a href="/study/game/directstorage.html">DirectStorageの発行と展開</a></p><p>パック全体を一つの圧縮ストリームにすると、途中の素材を変えたときに圧縮状態や後続の位置が変わり、圧縮後のバイト列で比較した差が広がる場合があります。配布システムがパックファイル単位で交換する構成なら、変更した素材が小さくてもパック全体が取得対象です。配信単位を分けたり、独立に展開できるブロックを安定した境界で作ったりすると、変更範囲を狭められます。再取得量は配信側がどの単位を識別し再利用するかでも変わります。たとえばEpic Gamesのプラットフォーム非依存パッチ手順ではクック済みのパッケージが差し替えの単位で、Unity Addressablesのコンテンツ更新では変更されたアセットを新しいバンドルから参照するカタログを作れます。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/how-to-create-a-patch-in-unreal-engine" target="_blank" rel="noreferrer">Epic Gamesのパッチ作成手順</a> · <a href="https://docs.unity3d.com/ja/Packages/com.unity.addressables%401.20/manual/ContentUpdateWorkflow.html" target="_blank" rel="noreferrer">Unity Addressablesのコンテンツ更新ビルド</a></p><h2 id="マニフェストが、その版で使う配布物を指す" tabindex="-1">マニフェストが、その版で使う配布物を指す <a class="header-anchor" href="#マニフェストが、その版で使う配布物を指す" aria-label="Permalink to &quot;マニフェストが、その版で使う配布物を指す&quot;">​</a></h2><p><strong>マニフェスト</strong>は、ある配布版が必要とするデータの一覧です。例えば対象機種、対応する実行ファイルの版、各配布単位の識別子・サイズ・内容ハッシュを記録します。次の例ではパックごとに再利用を判定します。<code>a1…</code>などはハッシュを省略した表記です。</p><table tabindex="0"><thead><tr><th>配信単位</th><th>配布版17</th><th>配布版18</th><th>17から18への更新</th></tr></thead><tbody><tr><td>共通素材 <code>base</code></td><td>280 MiB、<code>a1…</code></td><td>280 MiB、<code>a1…</code></td><td>検証済みのデータを再利用する。</td></tr><tr><td>街の更新素材 <code>town</code></td><td>12 MiB、<code>b2…</code></td><td>12 MiB、<code>c3…</code></td><td>新しい12 MiBを取得する。</td></tr></tbody></table><p>この設計で取得するデータは、新しいマニフェストと変更された12 MiBのパックです。別の方式では、旧版のファイルを入力として、配信したバイナリ差分から新版を組み立てることもできます。その場合は、適用前に入力の版やハッシュを照合し、組み立てた出力を新版のハッシュと照合します。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/updating-unreal-engine-projects-with-patches-after-release" target="_blank" rel="noreferrer">Epic Gamesの配信方式の比較</a></p><figure class="study-figure"><img src="'+d+'" alt="配布版17と18のマニフェストは同じ共通素材a1を参照する。街の素材だけがb2からc3に変わり、新しい12 MiBを取得して検証する。準備できた時点で使用中のマニフェストを18に切り替える。" width="760" height="424" loading="lazy"><figcaption>共通素材を再利用し、変更された配信単位の準備ができてから参照先を切り替えます。<a href="/study/images/game/asset-build-and-patches.svg" target="_blank" rel="noopener noreferrer">配布版の切り替えの図を拡大</a></figcaption></figure><h2 id="検証した版へ切り替え、途中で止まった場合に備える" tabindex="-1">検証した版へ切り替え、途中で止まった場合に備える <a class="header-anchor" href="#検証した版へ切り替え、途中で止まった場合に備える" aria-label="Permalink to &quot;検証した版へ切り替え、途中で止まった場合に備える&quot;">​</a></h2><ol><li><strong>別の領域に準備する。</strong> 新しいマニフェストの対象機種と互換性を確認し、不足する配布物を取得する。旧版を使用したまま準備できるように、必要な一時容量も見積もる。</li><li><strong>一式を検証する。</strong> 信頼できる配布元から得たマニフェストを基準に、サイズ、内容ハッシュ、形式、依存先を確認する。再利用する配布物も検証済みのものを使う。<a href="/study/data/binary-file-validation.html">バイナリファイルの検証</a></li><li><strong>参照先を切り替える。</strong> 必要なファイルがすべて揃った配布版だけを選べるようにし、その版のマニフェストへ切り替える。稼働中のローダーは開始時に選んだ版を使い続け、新しい版は再起動など区切りのよい時点から読み込む。</li><li><strong>起動時に復旧する。</strong> 更新の途中で停止した場合に備え、新版を開けないときは検証済みの旧版へ戻せるようにする。旧版を使っている処理が終わり、復旧にも不要になった時点で古いデータを片付ける。</li></ol><p>切り替えに使うファイル操作の契約と、電源断後にどの版が残るかは別々に確認します。取得中、検証後、切り替え直後に中断する場合を試し、次回起動で使用できる一式を選べるか確認します。<a href="/study/os/file-write-and-durability.html">ファイルの書き込みと永続化</a></p>',17)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
